const additionalData = target.additional_data || (target.additional_data = {});
const tabController = window.tabViewsController;
const tabViewControl = window.getViewersTabs();
const isEditorActive = tabViewControl.getCurrentTabId() === 'editor_container';

if (isEditorActive) {
	const { tdfSettings } = tabController.shareData;
	const xmlSchema = window.aras.getItemProperty(window.item, 'xml_schema');
	const { importManager } = additionalData;

	importManager
		?.import(null, {
			reading: {
				readContent: true,
				saveFile: true,
			},
			contextData: {
				xmlSchema: xmlSchema,
				contentBuilder: tdfSettings['datamodel.documentContentGetter'],
			},
		})
		.then((result) => {
			if (result) {
				const editorWindow =
					tabController.views['editor_container'].domNode
						.contentWindow;
				const { viewController } = editorWindow;

				viewController.openImportPanel(result);
			}
		});
} else {
	window.aras.AlertError(
		window.aras.getResource(
			'../Modules/aras.innovator.TDF',
			'importcontent.noteditortab'
		)
	);
}
